async function loadWishlistSlugs() {
  if (wishlistSlugsPromise) return wishlistSlugsPromise;
  wishlistSlugsPromise = (async () => {
    if (getApiBase()) {
      try {
        const result = await apiRequest<{ data?: ProductData[] }>("/account/wishlist");
        return new Set((result.data || []).map((item) => item.slug));
      } catch { /* guest visitors use local wishlist */ }
    }
    try {
      const items = JSON.parse(window.localStorage.getItem("drone-bangladesh-wishlist") || "[]") as ProductData[];
      return new Set(items.map((item) => item.slug));
    } catch { return new Set<string>(); }
  })();
  return wishlistSlugsPromise;
}

function getCartCount() {
  if (typeof window === "undefined") return 0;
  try {
    return JSON.parse(window.localStorage.getItem(cartKey) || "[]").reduce((sum: number, item: { quantity?: number }) => sum + (item.quantity || 1), 0);
  } catch { return 0; }
}

async function addToCart(product: ProductData) {
  if (typeof window === "undefined") return;
  if (getApiBase()) {
    try {
      const apiResult = await apiRequest<{ data?: { items?: Array<{ slug: string; name: string; image?: string; price: number; quantity: number }> } }>("/cart/items", { method: "POST", body: JSON.stringify({ slug: product.slug, quantity: 1 }) });
      // Mirror to localStorage so checkout fallback always works
      if (apiResult?.data?.items?.length) {
        try { window.localStorage.setItem(cartKey, JSON.stringify(apiResult.data.items)); } catch { /* ignore */ }
      } else {
        apiRequest<{ data?: { items?: Array<{ slug: string; name: string; image?: string; price: number; quantity: number }> } }>("/cart")
          .then(r => { if (r?.data?.items?.length) { try { window.localStorage.setItem(cartKey, JSON.stringify(r.data.items)); } catch { /* ignore */ } } })
          .catch(() => {});
      }
      window.dispatchEvent(new Event("drone-cart-updated"));
      return;
    } catch (e) {
      console.warn("API addToCart failed, falling back to local storage", e);
    }
  }
  const cart = JSON.parse(window.localStorage.getItem(cartKey) || "[]") as Array<ProductData & { quantity: number }>;
  const existing = cart.find((item) => item.slug === product.slug);
  if (existing) existing.quantity += 1;
  else cart.push({ ...product, quantity: 1 });
  window.localStorage.setItem(cartKey, JSON.stringify(cart));
  window.dispatchEvent(new Event("drone-cart-updated"));
}

