function MobileMenuAccordion({ label, open, accent = false, onToggle, children }: { label: string; open: boolean; accent?: boolean; onToggle: () => void; children: ReactNode }) {
  return <section className={tw(`mobile-store-section ${open ? "is-open" : ""}`)}>
    <button type="button" className={tw(`mobile-store-section-trigger ${accent ? "accent" : ""}`)} onClick={onToggle} aria-expanded={open}>{label}{open ? <ChevronUp size={22} /> : <ChevronDown size={22} />}</button>
    {open && <div className={utilities("mobile-store-section-content", [1340, "[@media_(max-width:_720px)]:[:where(&).mobile-store-section-content]:[padding:2px_0_10px]"])}>{children}</div>}
  </section>;
}

function MobileStoreMenu({ onClose }: { onClose: () => void }) {
  const pathname = usePathname();
  const menuRef = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    menuRef.current?.showModal();
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = previousOverflow; };
  }, []);
  const links = [
    { label: "Home", href: "/" },
    ...clothingNavigation,
    { label: "All Products", href: "/products" },
    { label: "Contact", href: "/contact" },
  ];
  return <dialog ref={menuRef} aria-label="Mobile navigation" className="m-0 h-dvh max-h-none w-[min(360px,92vw)] max-w-none border-0 bg-white p-0 text-[#102b4d] shadow-2xl backdrop:bg-black/50" onCancel={event => { event.preventDefault(); onClose(); }} onClick={event => { if (event.target === event.currentTarget) onClose(); }}>
    <div className="min-h-full p-5">
      <div className="mb-5 flex items-center justify-between border-b border-slate-200 pb-4">
        <h2 className="text-xl font-bold">Menu</h2>
        <button type="button" onClick={onClose} aria-label="Close menu" className="grid size-11 place-items-center rounded-full bg-slate-100"><X size={22}/></button>
      </div>
      <nav aria-label="Mobile primary navigation" className="flex flex-col gap-1">
        {links.map(item => <Link key={item.href} href={item.href} onClick={onClose} aria-current={pathname === item.href ? "page" : undefined} className={`flex min-h-14 items-center justify-between rounded-lg px-3 text-base font-semibold hover:bg-slate-100 focus-visible:outline-2 focus-visible:outline-blue-600 ${pathname === item.href ? "bg-blue-50 text-blue-700" : ""}`}>{item.label}<ChevronRight size={18}/></Link>)}
      </nav>
      <div className="mt-6 flex flex-col gap-4 border-t border-slate-200 px-3 pt-5 text-base">
        <Link href="/wishlist" onClick={onClose} className="flex items-center gap-2"><Heart size={18}/>Wishlist</Link>
        <Link href="/track-order" onClick={onClose}>Track Order</Link>
        <Link href="/account" onClick={onClose} className="flex items-center gap-2"><UserRound size={18}/>Sign In</Link>
      </div>
    </div>
  </dialog>;
}

