export function MobileBottomNav() {
  const pathname = usePathname();
  const [cartCount, setCartCount] = useState(0);
  const [wishlistCount, setWishlistCount] = useState(0);
  useEffect(() => {
    let active = true;
    let revision = 0;
    async function updateCart() {
      const current = ++revision;
      setCartCount(getCartCount());
      if (!getApiBase()) return;
      try {
        const response = await apiRequest<{data?:{items?:Array<{quantity?:number}>}}>("/cart", {cache:"no-store"});
        if (active && current === revision) setCartCount((response.data?.items || []).reduce((sum,item)=>sum + Number(item.quantity || 0),0));
      } catch { /* local cart remains available */ }
    }
    function updateWishlist() { void loadWishlistSlugs().then(slugs=>{if(active)setWishlistCount(slugs.size);}); }
    function refresh() { void updateCart(); updateWishlist(); }
    function storage(event: StorageEvent) {
      if (!event.key || event.key === "drone-bangladesh-cart") void updateCart();
      if (!event.key || event.key === "drone-bangladesh-wishlist") { wishlistSlugsPromise=null; updateWishlist(); }
    }
    refresh();
    window.addEventListener("drone-cart-updated",updateCart);
    window.addEventListener("drone-wishlist-updated",updateWishlist);
    window.addEventListener("storage",storage);
    window.addEventListener("focus",refresh);
    return ()=>{
      active=false; revision++;
      window.removeEventListener("drone-cart-updated",updateCart);
      window.removeEventListener("drone-wishlist-updated",updateWishlist);
      window.removeEventListener("storage",storage);
      window.removeEventListener("focus",refresh);
    };
  },[pathname]);
  const items = [
    {href:"/",label:"Home",icon:<Home size={22}/>},
    {href:"/products",label:"Shop",icon:<LayoutGrid size={22}/>},
    {href:"/cart",label:"Cart",icon:<ShoppingCart size={22}/>,badge:cartCount},
    {href:"/wishlist",label:"Wishlist",icon:<Heart size={22}/>,badge:wishlistCount},
    {href:"/account",label:"Sign In",icon:<UserRound size={22}/>},
  ];
  return <nav className={mobileNavStyles.nav} aria-label="Mobile bottom navigation">
    {items.map(item=>{
      const isActive = item.href === "/" ? pathname === "/" : item.href === "/products" ? /^\/(products|categories|search)(\/|$)/.test(pathname) : pathname.startsWith(item.href);
      return <Link key={item.href} href={item.href} className={`${mobileNavStyles.item} ${isActive ? mobileNavStyles.active : ""}`} aria-current={isActive ? "page" : undefined} aria-label={item.badge ? `${item.label}, ${item.badge} items` : item.label}>
        <span className={mobileNavStyles.icon}>{item.icon}{!!item.badge && <span className={mobileNavStyles.badge} aria-hidden="true">{item.badge>99?"99+":item.badge}</span>}</span>
        <span>{item.label}</span>
      </Link>;
    })}
  </nav>;
}

